import numpy as np
import matplotlib.pyplot as plt

# Initial number of bacteria
initial_bacteria = 100

# Time interval (hours)
time_intervals = np.arange(0, 25, 3)

# Doubling time (hours)
doubling_time = 3

# Function to calculate the number of bacteria at a given time
def bacteria_count(t, initial, doubling_time):
    return initial * (2 ** (t / doubling_time))

# Calculate the number of bacteria for each time interval
bacteria_counts = bacteria_count(time_intervals, initial_bacteria, doubling_time)

# Plot the growth curve
plt.plot(time_intervals, bacteria_counts, label='Bacterial Growth')
plt.xlabel('Time (hours)')
plt.ylabel('Number of Bacteria')
plt.title('Bacterial Growth over Time')
plt.legend()
plt.show()

# Return the number of bacteria after 24 hours
bacteria_after_24_hours = bacteria_count(24, initial_bacteria, doubling_time)
